// Metadata returns fresh policy metadata for every generated tool.
func Metadata() []policy.ToolMetadata {
	return []policy.ToolMetadata{
		{
			ID:          ApproveMerge,
			Title:       "Approve Merge",
			Description: "Approve the confirmed Change Card revision after its CP4 verification report passed for the candidate commit. Requires a promotion target, such as surla serve -promotion-config.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          CheckProject,
			Title:       "Check Project",
			Description: "Run the workspace's Go tests on the current uncommitted files in an isolated Linux container. No input. Returns passed and a message with the first failure; when it says the output was cut, read the rest with read_check_output(op_id). If the message says go.sum or go.work.sum needs entries or go.mod needs an update, call update_dependencies and check again.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          ConfigureModel,
			Title:       "Configure Model",
			Description: "Switch the model provider and model name (such as anthropic/claude-sonnet-4-6 or openai/gpt-5.4-mini, using the API key in surla serve's environment) or attach a running model gateway address, without restarting surla serve. Live targets that start_live_target starts afterwards plan with this model.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          ConfirmIntent,
			Title:       "Confirm Intent",
			Description: "Confirm or refine Checkpoint 1 ambiguity answers and example checks for the card's current request_revision. To record a decision that no option expresses, call revise_change with that decision in prompt.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          Diff,
			Title:       "Diff",
			Description: "Compute structural Goa design and go.mod dependency diffs.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          DraftOverride,
			Title:       "Draft Override",
			Description: "Hot-reload a prompt template in 0s or flag a compiled business rule change. A prompt template needs a bound target; on surla serve, call start_live_target with a candidate commit first.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          GenerateCode,
			Title:       "Generate Code",
			Description: "Regenerate code from local edited design files without uploading source. Omit target for the application, or use target eval for the public local eval/ module. Return sorted module-relative files_written and warnings. This compiles the design only; run check_project to build and test the application before verification. Fix a rejected design and call again on the same server.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          GetChange,
			Title:       "Get Change",
			Description: "Read the current Checkpoint 1 Change Card and its request_revision.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          GetStoryRefresh,
			Title:       "Get Story Refresh",
			Description: "Read the current Story refresh operation for the bound workspace: op_id, state (none, running, succeeded, or failed), snapshot_digest, stories, or diagnostic. Takes no input. When state is none, call refresh_story first.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          GetVerification,
			Title:       "Get Verification",
			Description: "Read the state of a CP4 verification run started by verify_change.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          InitProject,
			Title:       "Init Project",
			Description: "Initialize a new Surla starter project inside the bound workspace directory, create its initial Git commit, and switch the server's active workspace to that project. Returns the created commit ID in commit for start_live_target and verify_change.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          ListTraces,
			Title:       "List Traces",
			Description: "Read your saved operation diagnostics, newest first. status filters all spans, recorded errors, or spans without an error status. Empty spans with has_more true still leaves older history to examine: pass next_cursor as cursor with the same filter. Omit cursor to refresh. Summaries exclude raw errors and inputs; unset status does not prove success. No top-level span currently exists for preview_architecture, verify_change, approve_merge, confirm_intent, get_change, diff or non-live draft_override; requests rejected before span creation and separate verification processes are also absent. An instrumented child operation may appear separately. not_implemented means the server operator must enable recording; it is not an empty history.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          ListVerifications,
			Title:       "List Verifications",
			Description: "List all CP4 verification runs started for a Change Card, newest first.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          PreviewArchitecture,
			Title:       "Preview Architecture",
			Description: "Preview Checkpoint 2 C4 container topology and Goa-AI guardrails for a confirmed Change Card. Surla reads the candidate module from the bound workspace. It reports what the design declares; it does not compare the design with the Change Card's requirements.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          ProposeChange,
			Title:       "Propose Change",
			Description: "Propose a feature change as a Checkpoint 1 Change Card. Read the target's design/*.go and the surla://golden-path playbook first, then send the request in prompt with your analysis of it: a summary, the open questions only the requester can answer (an empty list when none), concrete examples that become checks, and the existing behaviors the change must keep. When adopting a workspace Story, pass the succeeded refresh_story operation's op_id in story_refresh_op_id. Surla assigns the IDs and request_revision and saves the card; a card without open questions is confirmed at once. When story_refresh_op_id is omitted and a workspace is bound, Surla records design/*.go from the bound workspace.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          ReadCheckOutput,
			Title:       "Read Check Output",
			Description: "Read the next page of a check_project or update_dependencies output. Pass op_id from that result and next_cursor from the previous page; omit cursor for the first page. dropped_bytes > 0 means part of the output was not captured.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          RefreshStory,
			Title:       "Refresh Story",
			Description: "Start or reuse a sandboxed Story evaluation of the bound workspace's current design files and return op_id, state, and snapshot_digest promptly. Takes no input. Poll get_story_refresh until state is succeeded or failed.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          ReviseChange,
			Title:       "Revise Change",
			Description: "Revise an existing Checkpoint 1 Change Card with updated requirements bound to its current request_revision. Send the revised request in prompt with a new analysis made against the current card (as get_change returns it) and the target's design: keep or edit each current example through prior_id, list the dropped ones in removed_example_ids, and restate the confirmed decisions that still hold in summary, examples or preserved_behaviors. Pass story_refresh_op_id from a succeeded refresh_story operation to adopt an updated workspace Story, or omit story_refresh_op_id on a card with Stories to keep its agreed Story and its design source. The new revision's answers, confirmed_by and any approval are cleared, so it needs confirmation again.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          StartLiveTarget,
			Title:       "Start Live Target",
			Description: "Build a candidate commit and run it as this server's live CP3 target so draft_override can try prompt text on it. This first stops the target already running, which discards every prompt draft applied to it, even if the new build then fails. Prompt text survives only when it is committed. Requires a committed starter project in the bound workspace or -verification-config.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          StopLiveTarget,
			Title:       "Stop Live Target",
			Description: "Stop this server's live CP3 target, if one runs. This discards every prompt draft applied to it; prompt text survives only when it is committed.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          UpdateDependencies,
			Title:       "Update Dependencies",
			Description: "Add missing requirements and checksums for the workspace's Go modules (go mod tidy) and write the changed go.mod, go.sum and go.work.sum. No input. Call it when check_project reports a missing go.sum or go.work.sum entry or a needed go.mod update, then call check_project again.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          VerifyChange,
			Title:       "Verify Change",
			Description: "Start CP4 verification of a candidate commit for the confirmed Change Card revision; returns a run_id to read with get_verification. Requires a committed starter project in the bound workspace or -verification-config.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
	}
}

// Names returns the identifiers of all generated tools.
func Names() []tools.Ident {
	return []tools.Ident{
		ApproveMerge,
		CheckProject,
		ConfigureModel,
		ConfirmIntent,
		Diff,
		DraftOverride,
		GenerateCode,
		GetChange,
		GetStoryRefresh,
		GetVerification,
		InitProject,
		ListTraces,
		ListVerifications,
		PreviewArchitecture,
		ProposeChange,
		ReadCheckOutput,
		RefreshStory,
		ReviseChange,
		StartLiveTarget,
		StopLiveTarget,
		UpdateDependencies,
		VerifyChange,
	}
}

// RequiredLabels lists the run label keys this toolset's Inject-populated
// tools require to be present via WithLabels(...) at run start. The runtime
// validates coverage across every toolset an agent uses before starting a
// run, so a missing label fails fast instead of surfacing mid-run as a tool
// call error.
func RequiredLabels() []string {
	return []string{}
}

// Spec returns the specification for the named tool if present.
func Spec(name tools.Ident) (tools.ToolSpec, bool) {
	switch name {
	case ApproveMerge:
		return newSpecApproveMerge(), true
	case CheckProject:
		return newSpecCheckProject(), true
	case ConfigureModel:
		return newSpecConfigureModel(), true
	case ConfirmIntent:
		return newSpecConfirmIntent(), true
	case Diff:
		return newSpecDiff(), true
	case DraftOverride:
		return newSpecDraftOverride(), true
	case GenerateCode:
		return newSpecGenerateCode(), true
	case GetChange:
		return newSpecGetChange(), true
	case GetStoryRefresh:
		return newSpecGetStoryRefresh(), true
	case GetVerification:
		return newSpecGetVerification(), true
	case InitProject:
		return newSpecInitProject(), true
	case ListTraces:
		return newSpecListTraces(), true
	case ListVerifications:
		return newSpecListVerifications(), true
	case PreviewArchitecture:
		return newSpecPreviewArchitecture(), true
	case ProposeChange:
		return newSpecProposeChange(), true
	case ReadCheckOutput:
		return newSpecReadCheckOutput(), true
	case RefreshStory:
		return newSpecRefreshStory(), true
	case ReviseChange:
		return newSpecReviseChange(), true
	case StartLiveTarget:
		return newSpecStartLiveTarget(), true
	case StopLiveTarget:
		return newSpecStopLiveTarget(), true
	case UpdateDependencies:
		return newSpecUpdateDependencies(), true
	case VerifyChange:
		return newSpecVerifyChange(), true
	default:
		return tools.ToolSpec{}, false
	}
}

